# voz-orquestrador.tf -- funcao que abre o stream de Transcribe e
# publica o instante de fim de fala como marco zero do orcamento.

resource "aws_lambda_function" "orquestrador_voz" {
  function_name = "${var.projeto}-orquestrador-voz"
  runtime       = "dotnet8"
  handler       = "OrquestradorVoz::OrquestradorVoz.Function::HandlerAsync"
  role          = aws_iam_role.orquestrador_voz.arn
  timeout       = 8  # folga sobre os 2,5 s do orcamento -- nao e o mesmo numero
  memory_size   = 512

  environment {
    variables = {
      ORCAMENTO_MS      = "2500"
      KNOWLEDGE_BASE_ID = aws_bedrockagent_knowledge_base.politica_atendimento.id
      REDIS_ENDPOINT    = aws_elasticache_replication_group.contexto_ligacao.primary_endpoint_address
    }
  }
}

resource "aws_connect_contact_flow" "atendimento_voz_rag" {
  instance_id = var.connect_instance_id
  name        = "atendimento-voz-rag"
  type        = "CONTACT_FLOW"
  # O conteudo real e um JSON exportado do designer visual do Connect --
  # aqui, o essencial e que o bloco "Invoke AWS Lambda function" chama o
  # orquestrador, e o bloco seguinte confere o atributo "escalonar" para
  # decidir entre reproduzir audio ou transferir para a fila humana.
  content = file("${path.module}/fluxos/atendimento-voz-rag.json")
}

resource "aws_cloudwatch_log_group" "orquestrador_voz" {
  name              = "/aws/lambda/${aws_lambda_function.orquestrador_voz.function_name}"
  retention_in_days = 30
}

// OrquestradorVoz.cs -- abre o stream de Transcribe e marca o instante
// de fim de fala como o marco zero do orcamento de 2,5 s.

public sealed class OrquestradorVoz
{
    private const int OrcamentoMs = 2500;
    private readonly TranscribeStreamingClient _transcribe;
    private readonly Stopwatch _relogio = new();

    public async Task<ResultadoLigacao> ProcessarAsync(Stream audioEntrada, CancellationToken ct)
    {
        var requisicao = new StartStreamTranscriptionRequest
        {
            LanguageCode = LanguageCode.PtBR,
            MediaSampleRateHertz = 8000,
            MediaEncoding = MediaEncoding.Pcm,
        };

        var resposta = await _transcribe.StartStreamTranscriptionAsync(requisicao, ct);
        var textoParcial = new StringBuilder();

        await foreach (var evento in resposta.TranscriptResultStream.WithCancellation(ct))
        {
            if (evento is TranscriptEvent te)
            {
                foreach (var resultado in te.Transcript.Results)
                {
                    // Resultado PARCIAL: ja processavel, mas ainda pode mudar.
                    // Nao inicia o temporizador -- so o resultado FINAL marca o
                    // fim de fala, que e o marco zero real do orcamento.
                    if (!resultado.IsPartial)
                    {
                        textoParcial.Append(resultado.Alternatives[0].Transcript);
                        _relogio.Restart();  // marco zero: 2500 ms comecam a contar aqui
                    }
                }
            }
        }

        return await ContinuarComOrcamentoAsync(textoParcial.ToString(), ct);
    }

    private Task<ResultadoLigacao> ContinuarComOrcamentoAsync(string texto, CancellationToken ct)
    {
        // MsRestante e consultado antes de CADA etapa custosa a seguir --
        // cache, busca no RAG, geracao -- para decidir se ainda ha tempo
        // ou se e hora de escalonar direto, sem tentar mais nada.
        int msRestante = OrcamentoMs - (int)_relogio.ElapsedMilliseconds;
        return DecidirProximaEtapaAsync(texto, msRestante, ct);
    }

    private Task<ResultadoLigacao> DecidirProximaEtapaAsync(string texto, int msRestante, CancellationToken ct)
        => throw new NotImplementedException("segue no roteador de modelo");
}

// ContextoLigacaoCacheService.cs -- cache-aside por ID de contato do
// Connect, nao pela chave normalizada global de pergunta do L89. Uma
// ligacao e uma conversa continua: o mesmo contexto pode valer para
// mais de uma pergunta DENTRO da mesma chamada.

public sealed class ContextoLigacaoCacheService
{
    private readonly IConnectionMultiplexer _redis;
    // TTL curto e fixo -- diferente do TTL por tipo de conteudo do L89,
    // porque aqui o que importa e a duracao da LIGACAO, nao o quanto o
    // CONTEUDO tolera ficar desatualizado.
    private static readonly TimeSpan TtlLigacao = TimeSpan.FromMinutes(10);

    public ContextoLigacaoCacheService(IConnectionMultiplexer redis) => _redis = redis;

    public async Task<string?> ObterContextoAsync(string contatoId, string topico)
    {
        var chave = $"voz:{contatoId}:{topico}";
        var db = _redis.GetDatabase();
        var valor = await db.StringGetAsync(chave);
        return valor.HasValue ? valor.ToString() : null;  // null = MISS, busca no RAG
    }

    public async Task GravarContextoAsync(string contatoId, string topico, string contextoRecuperado)
    {
        var chave = $"voz:{contatoId}:{topico}";
        var db = _redis.GetDatabase();
        await db.StringSetAsync(chave, contextoRecuperado, TtlLigacao);
        // TTL renova a cada gravacao -- uma ligacao ativa mantem o contexto
        // vivo; uma ligacao encerrada libera a chave em ate 10 minutos,
        // sem exigir limpeza explicita ao fim da chamada.
    }
}

// RoteadorPorLatencia.cs -- filtra por restricao de tempo ANTES de
// considerar qualidade. O modelo potente do L83 nunca entra na lista
// de opcoes deste canal, porque seu p99 medido nao cabe no orcamento.

public sealed class RoteadorPorLatencia
{
    // p99 de geracao medido em producao, em ms, por modelo -- atualizado
    // pela suite de avaliacao continua, nao decidido uma vez e esquecido.
    private static readonly Dictionary<string, int> P99PorModeloMs = new()
    {
        ["amazon.nova-lite-v1:0"]          = 780,
        ["anthropic.claude-haiku-4-5-..."]  = 910,
        ["anthropic.claude-sonnet-4-5-..."] = 1480,  // o modelo potente do L83
    };

    public string EscolherModelo(int msRestanteAposRecuperacao)
    {
        // So entram na lista os modelos cujo p99 CABE no que sobrou do
        // orcamento depois de transcricao e busca -- comparar qualidade
        // entre modelos que nem cabem no prazo e tempo perdido.
        var elegiveis = P99PorModeloMs
            .Where(m => m.Value <= msRestanteAposRecuperacao)
            .OrderByDescending(m => m.Value)  // entre os elegiveis, o MAIS
            .ToList();                         // capaz que ainda cabe no prazo

        if (elegiveis.Count == 0)
        {
            // Nenhum modelo cabe no tempo restante -- nao e hora de arriscar
            // uma chamada que provavelmente vai estourar; e hora de escalonar.
            throw new OrcamentoEsgotadoException(msRestanteAposRecuperacao);
        }

        return elegiveis.First().Key;
    }
}

public sealed class OrcamentoEsgotadoException : Exception
{
    public OrcamentoEsgotadoException(int msRestante)
        : base($"Nenhum modelo cabe nos {msRestante} ms restantes -- escalonar.") { }
}

# escalonamento.tf -- fila e perfil de roteamento que recebem a
# transferencia quando o orquestrador marca o atributo "escalonar".

resource "aws_connect_queue" "escalonamento_rag_voz" {
  instance_id           = var.connect_instance_id
  name                  = "escalonamento-rag-voz"
  description           = "Fila para ligacoes que estouraram o prazo ou a confianca do RAG por voz"
  hours_of_operation_id = var.hours_of_operation_id
}

resource "aws_connect_routing_profile" "atendentes_rag_voz" {
  instance_id               = var.connect_instance_id
  name                      = "atendentes-rag-voz"
  default_outbound_queue_id = aws_connect_queue.escalonamento_rag_voz.queue_id

  media_concurrencies {
    channel     = "VOICE"
    concurrency = 1
  }

  queue_configs {
    channel  = "VOICE"
    priority = 1
    queue_id = aws_connect_queue.escalonamento_rag_voz.queue_id
  }
}

// GatilhoEscalonamento.cs -- avalia os DOIS gatilhos sempre, e grava
// os atributos que o fluxo de contato do Connect le para decidir rota.

public sealed class GatilhoEscalonamento
{
    private const double LimiarSimilaridade = 0.70;
    private readonly AmazonConnectClient _connect;

    public async Task<DecisaoLigacao> AvaliarAsync(
        string contatoId, int msRestante, double similaridadeTrecho,
        string transcricao, string trechosRecuperados)
    {
        // Os dois gatilhos sao avaliados SEMPRE -- nenhum e "reserva" do
        // outro. Qualquer um dos dois, sozinho, decide escalonar.
        var estourouPrazo = msRestante <= 0;
        var confiancaBaixa = similaridadeTrecho < LimiarSimilaridade;

        if (!estourouPrazo && !confiancaBaixa)
            return DecisaoLigacao.RespostaFalada;

        var motivo = estourouPrazo ? "prazo_estourado" : "confianca_baixa";

        // Contexto ANEXADO -- transcricao e trechos ja recuperados vao para
        // os atributos do contato, para o atendente humano continuar a
        // conversa em vez de pedir para o cliente repetir tudo.
        await _connect.UpdateContactAttributesAsync(new UpdateContactAttributesRequest
        {
            InstanceId = _instanceId,
            InitialContactId = contatoId,
            Attributes = new Dictionary<string, string>
            {
                ["escalonar"] = "true",
                ["motivoEscalonamento"] = motivo,
                ["transcricaoParcial"] = transcricao,
                ["contextoRecuperado"] = trechosRecuperados,
            },
        });

        return DecisaoLigacao.Escalonar;
        // O FLUXO de contato, nao esta funcao, e quem faz a transferencia --
        // um bloco "Check contact attributes" no Connect le "escalonar" e
        // roteia para a fila configurada em escalonamento.tf.
    }
}

# iam-bedrock-voz.tf -- o papel do orquestrador de voz SO pode invocar
# modelos da lista elegivel por latencia -- nunca o modelo potente do L83.

data "aws_iam_policy_document" "invocar_modelos_voz" {
  statement {
    effect  = "Allow"
    actions = ["bedrock:InvokeModelWithResponseStream"]
    resources = [
      "arn:aws:bedrock:${var.regiao}::foundation-model/amazon.nova-lite-v1:0",
      "arn:aws:bedrock:${var.regiao}::foundation-model/anthropic.claude-haiku-4-5-*",
    ]
    # O modelo potente (claude-sonnet-4-5) do L83 NAO aparece aqui -- o
    # papel do orquestrador de voz simplesmente nao tem permissao de
    # invoca-lo, mesmo que um bug no roteador tente.
  }
}

resource "aws_iam_role_policy" "orquestrador_voz_bedrock" {
  role   = aws_iam_role.orquestrador_voz.id
  policy = data.aws_iam_policy_document.invocar_modelos_voz.json
}
